#include "Source/ReferencePedals/Common/LowLatencyOversampler.h"
#include <complex>
#include <cstdio>
#include <ctime>
#include <vector>
using namespace luthier::reference::common;
struct Core{double z[4]{},a[4]{},step[4]{},phase=0,triangle=.5,sr=96000,tc=0;int counter=0;bool moving=false;void prepare(double rate,bool motion,double fc=3300){sr=rate;moving=motion;tc=1-exp(-1/(sr*.02));double g=tan(pi*fc/sr);for(auto& c:a)c=(g-1)/(g+1);}double process(double x){if(moving){double tri=phase<.65?phase/.65:(1-phase)/.35;triangle+=(tri-triangle)*tc;if(!counter){double fc=330*pow(10.,triangle);for(int k=0;k<4;++k){double g=tan(pi*fc*(1+.01*(k-1.5))/sr);step[k]=((g-1)/(g+1)-a[k])/8;}}for(int k=0;k<4;++k)a[k]+=step[k];counter=(counter+1)&7;phase+=1.5/sr;if(phase>=1)phase-=1;}double wet=x;for(int k=0;k<4;++k){double y=a[k]*wet+z[k];z[k]=wet-a[k]*y;wet=y/sqrt(1+.04*y*y);}return .5*(x+wet);}};
int main(){for(double sr:{44100.,48000.,96000.,192000.}){LowLatencyOversampler os;os.prepareFactor(sr,sr<=48000?2:1);Core c;c.prepare(os.rate(),false);double expected=sr*os.factor()/pi*atan(tan(pi*3300/(sr*os.factor()))*tan(3*pi/8));std::complex<double> bin{};for(int i=0;i<int(sr);++i){double y=os.process(i==0?.00001:0,[&](double x){return c.process(x);});bin+=y*exp(std::complex<double>(0,-2*pi*expected*i/sr));}printf("sr%.0f notch %.5fHz error %.4f%% residual%.3g latency%d\n",sr,expected,(expected/(3300*tan(3*pi/8))-1)*100,abs(bin)/.00001,os.latencySamples());}
LowLatencyOversampler os[2];Core c[2];for(int k=0;k<2;++k){os[k].prepareFactor(48000,2);c[k].prepare(96000,true);}std::vector<double> input(480000);for(int i=0;i<480000;++i)input[i]=.1*sin(i*.13);timespec start{},end{};clock_gettime(CLOCK_THREAD_CPUTIME_ID,&start);double sum=0;for(double x:input)for(int k=0;k<2;++k)sum+=os[k].process(x,[&](double v){return c[k].process(v);});clock_gettime(CLOCK_THREAD_CPUTIME_ID,&end);double seconds=end.tv_sec-start.tv_sec+(end.tv_nsec-start.tv_nsec)*1e-9;printf("2x core-only CPU %.6f%% sum%.9f\n",seconds*10,sum);}
